pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 _unlockTime, uint256 putEther) public {
        // Restrict to admissible parameters: unlockTime in the past can be chosen,
        // and msg.value must not overflow the balance (require checks it is safe, but
        // we keep it bounded so it does not revert before reaching the interesting line).
        vm.assume(putEther <= type(uint128).max);

        // Warp to a known future timestamp so that a low _unlockTime is clearly in the past.
        uint256 farFuture = block.timestamp + 365 days;
        vm.warp(farFuture);

        // Fund and call Put from an arbitrary caller.
        address caller = address(uint160(uint256(keccak256(abi.encode(block.timestamp)))));
        vm.deal(caller, putEther);
        vm.prank(caller);
        c.Put{value: putEther}(_unlockTime);

        // The invariant: the recorded unlock time for caller must be >= block.timestamp at call time.
        // In the reference contract, `acc.unlockTime = _unlockTime>block.timestamp?_unlockTime:block.timestamp;`
        // ensures it is always >= block.timestamp. The buggy version sets it to `_unlockTime` directly,
        // which can be arbitrarily small, violating the invariant.
        (uint256 storedUnlockTime, ) = c.Acc(caller);
        assertTrue(storedUnlockTime >= farFuture);
    }
}

