pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 pastTime, uint128 depositAmount) public {
        // Restrict _unlockTime to be strictly in the past relative to the current block timestamp
        vm.assume(pastTime < block.timestamp);
        // Ensure the deposit amount is at least MinSum (1 ether) to meet collection threshold
        vm.assume(depositAmount >= 1 ether);
        // Ensure no overflow
        vm.assume(depositAmount <= type(uint128).max);

        address caller = address(0x1234);
        vm.deal(caller, depositAmount);

        // First, make a Put to set up a balance with a past unlockTime (the buggy version allows this)
        vm.prank(caller);
        c.Put{value: depositAmount}(pastTime);

        // Warp to a time after the pastTime to make block.timestamp > pastTime
        vm.warp(pastTime + 1);

        // Attempt to Collect the same amount; on the reference, this must revert because
        // reference Put would have set unlockTime to block.timestamp (which is after pastTime+1),
        // while buggy Put sets it to pastTime, allowing Collect to succeed.
        bool collectReverts;
        vm.prank(caller);
        try c.Collect(depositAmount) {
            collectReverts = false;
        } catch {
            collectReverts = true;
        }

        // Reference: Collect must revert (block.timestamp is pastTime+1, but reference unlockTime >= original block.timestamp > pastTime+1)
        // Bug: Collect may succeed because unlockTime = pastTime < block.timestamp
        assertTrue(collectReverts);
    }
}

