pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initDeposit, uint256 putAmount, uint256 firstUnlock, uint256 secondUnlock) public {
        // Keep amounts reasonable
        vm.assume(initDeposit > 0 && initDeposit < 1000 ether);
        vm.assume(putAmount > 0 && putAmount < 1000 ether);
        // Ensure secondUnlock is strictly greater than firstUnlock to force a meaningful update attempt
        vm.assume(secondUnlock > firstUnlock);
        vm.assume(secondUnlock > block.timestamp);

        address sender = address(uint160(uint256(keccak256(abi.encode(initDeposit)))));
        vm.deal(sender, initDeposit + putAmount);

        // First Put sets an initial unlock time
        vm.prank(sender);
        c.Put{value: initDeposit}(firstUnlock);

        vm.warp(block.timestamp + 1);

        // Second Put tries to extend the unlock time
        vm.prank(sender);
        c.Put{value: putAmount}(secondUnlock);

        (uint actualUnlock, ) = c.Acc(sender);
        // In the reference contract, the unlock time is updated to secondUnlock (> current timestamp).
        // In the buggy contract, it stays at firstUnlock. In both cases the caller's unlockTime already
        // exists, but the reference guarantees actualUnlock == secondUnlock while the bug leaves it
        // as firstUnlock. This difference is detected by checking that actualUnlock is at least
        // firstUnlock + 1 (since secondUnlock > firstUnlock). The bug breaks this when secondUnlock > firstUnlock.
        assertTrue(actualUnlock > firstUnlock);
    }
}

