pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint256 _amount, uint256 _warpTime) public {
        // Admissible domain: amounts > 0 and >= MinSum, warp times around the unlock time
        _unlockTime = bound(_unlockTime, 0, type(uint64).max);
        _amount = bound(_amount, 1 ether, 100 ether);
        _warpTime = bound(_warpTime, 0, type(uint64).max);

        address alice = makeAddr("alice");
        vm.deal(alice, 100 ether);

        // Deposit with a specific unlockTime
        vm.prank(alice);
        c.Put{value: 10 ether}(_unlockTime);

        // Warp to a time that is potentially before the unlock time
        vm.warp(_warpTime);

        // Attempt Collect
        vm.prank(alice);
        bool ok;
        try c.Collect(_amount) returns (uint256) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: If Collect succeeds, the current time must be strictly after the unlock time.
        // The mutant violates this because it removes the unlock time check, allowing Collect
        // to succeed even when block.timestamp <= unlockTime.
        if (ok) {
            uint256 recordedUnlockTime = c.Acc(alice).unlockTime;
            assertTrue(block.timestamp > recordedUnlockTime);
        }
    }
}

