pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _amount, uint256 _unlockDelay, address _collector) public {
        // 1. bound the amount to a plausible range above MinSum and below a reasonable limit.
        uint256 minSum = c.MinSum();
        _amount = bound(_amount, minSum + 1, 1000 ether);
        // unlock delay must be > 0 for the lock to actually have meaning.
        _unlockDelay = bound(_unlockDelay, 1, 365 days);
        // the collector must be a different address than the test contract (which is the Log address),
        // to avoid self-destructing the Log contract. Also exclude address(0).
        vm.assume(_collector != address(this) && _collector != address(0));

        // 2. Set up the scenario: fund the collector and make a Put to lock funds with a future unlock time.
        vm.deal(_collector, _amount);
        uint256 putTime = block.timestamp;
        uint256 unlockTime = putTime + _unlockDelay;
        // Warp to the future so we can set an unlock time that is still in the future after we move back.
        // Actually it is simpler: stay in present, Put with a future unlockTime, then try to Collect.
        // We cannot warp backwards, so we do everything at current block.timestamp, and the unlockTime is in the future.
        vm.prank(_collector);
        c.Put{value: _amount}(unlockTime);

        // Collect before the unlock time. Since block.timestamp <= unlockTime, the reference should not allow Collect.
        // At this point block.timestamp is still <= unlockTime (strictly < if _unlockDelay >= 1).
        // We try to Collect, expecting revert in the reference version.
        bool refOk;
        vm.prank(_collector);
        try c.Collect(_amount) returns (uint256) {
            refOk = true;
        } catch {
            refOk = false;
        }

        // 3. The general rule: if block.timestamp <= unlockTime, a Collect that decreases the balance cannot succeed.
        // Since we saturated the conditions (balance >= MinSum, balance >= _amount, and _amount <= balance),
        // the only reason for revert in the reference is the unlock time check.
        // Here we check: the reference always reverts for this attempted premature Collect.
        assertTrue(!refOk, "Reference should have reverted because block.timestamp <= unlockTime");
    }
}

