pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint128 _amount, uint8 _warpOffset) public {
        // Ensure unlock time is in the future and amount meets minimum sum
        vm.assume(_unlockTime > block.timestamp);
        vm.assume(_amount >= 1 ether);
        // warpOffset determines how far we move past the unlock time (or not).
        // warpOffset = 0 => block.timestamp = _unlockTime (not strictly greater),
        // warpOffset > 0 => block.timestamp > _unlockTime (strictly greater).
        vm.assume(_warpOffset > 0);

        address actor = makeAddr("actor");
        vm.deal(actor, _amount);

        // Actor puts funds with a future unlock time
        vm.startPrank(actor);
        c.Put{value: _amount}(_unlockTime);
        vm.stopPrank();

        // Warp exactly to unlockTime + (offset - 1)
        // If offset == 1, warp to unlockTime (timestamp == unlockTime, NOT >)
        // If offset > 1, warp to unlockTime + (offset - 1) (timestamp > unlockTime)
        vm.warp(_unlockTime + uint256(_warpOffset) - 1);

        // Prepare a recipient that always accepts Ether
        address payable recipient = payable(makeAddr("recipient"));

        // Fuzz a small collect amount that doesn't exceed balance
        uint256 collectAmt = bound(uint256(keccak256(abi.encode(_unlockTime, _amount, _warpOffset))), 1 ether, _amount);

        uint256 balBefore = actor.balance;

        // Actor attempts to collect
        vm.prank(actor);
        c.Collect(collectAmt);

        uint256 balAfter = actor.balance;
        uint256 accBal = c.Acc(actor).balance;

        // The rule:
        // If balance decreased (i.e., funds were collected and sent), then block.timestamp MUST be > unlockTime.
        // The bug allows balance to decrease even when block.timestamp <= unlockTime.
        bool balanceDecreased = accBal < _amount;
        if (balanceDecreased) {
            assertTrue(block.timestamp > _unlockTime);
        } else {
            // If balance didn't decrease, the rule is vacuously satisfied.
            assertTrue(true);
        }
    }
}

