pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlock, uint256 amount, uint256 warpTime) public {
        // Keep values in admissible domain
        uint256 bal = 2 ether;
        vm.assume(amount <= bal && amount >= 1);
        vm.assume(unlock >= 1);
        vm.assume(warpTime <= unlock);

        // Setup a fresh account with balance and a future unlock time
        address actor = address(0x1234);
        vm.deal(actor, bal);
        vm.prank(actor);
        c.Put{value: bal}(unlock);

        // Warp to a time not after unlock time
        vm.warp(warpTime);

        // Try to collect; the reference should revert, the mutant may succeed
        bool ok;
        vm.prank(actor);
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference invariant: if block.timestamp <= unlockTime, Collect must revert
        // The mutant violates this by allowing success
        assertTrue(!ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address sender, uint256 amt) public payable {
        require(amt > 0 && amt <= 1 ether);
        require(msg.sender != sender);
        c.Put{value: 1 ether}(uint256(block.timestamp + 100));
        uint256 balBefore = c.Acc(sender);
        bool ok = this.collectViaC(sender, amt);
        uint256 balAfter = c.Acc(sender);
        assert(ok ? (balBefore + amt == balAfter) : true);
    }
    function collectViaC(address sender, uint256 amt) external returns (bool) {
        try c.Collect(amt) { return true; } catch { return false; }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am) public payable {
        require(true);
        uint balBefore = address(c).balance;
        bool reverted; try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        assert(!reverted ? balAfter <= balBefore : true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _caller, uint _am) public payable {
        require(true);
        uint balBefore = c.Acc(_caller).balance;
        bool reverted; try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        uint balAfter = c.Acc(_caller).balance;
        assert(!reverted -> balAfter == balBefore - _am);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint _am) public payable {
        require(true);
